  4	import type { FilesystemCommand, FilesystemSession } from './types'
  5	const envelopeKeys = ['version', 'session', 'generation', 'requestId', 'deadlineMs', 'operation']
  6	const operationKeys: Record<string, readonly string[]> = {
  7	  bind: ['root'], capabilities: [], dispose: [], mkdir: ['path'],
  8	  read: ['path', 'offset', 'length'], list: ['path', 'limit', 'cursor'],
  9	  'write-open': ['path', 'maxBytes'], 'write-chunk': ['handle', 'offset', 'data'],
 10	  'write-close': ['handle', 'sha256'], replace: ['handle', 'parent', 'name', 'sha256'],
 11	  remove: ['path', 'kind'],
 12	}
 13	const integer = (value: unknown, min: number, max: number): value is number =>
 14	  typeof value === 'number' && Number.isSafeInteger(value) && value >= min && value <= max
 15	const token = (value: unknown): value is string => typeof value === 'string' && /^[a-f0-9]{32}$/.test(value)
 16	const hash = (value: unknown): value is string => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value)
 17	export function safeFilesystemComponent(value: unknown): value is string {
 18	  return typeof value === 'string' && value.length > 0 && value.length <= 255 &&
 19	    value.normalize('NFC') === value && value !== '.' && value !== '..' &&
 20	    Array.from(value).every(char => char.charCodeAt(0) > 31 && char.charCodeAt(0) !== 127) &&
 21	    !/[<>:"/\\|?*]/.test(value) && !/[. ]$/.test(value) &&
 22	    !/^(CON|PRN|AUX|NUL|COM[1-9¹²³]|LPT[1-9¹²³])(?:\.|$)/i.test(value)
 23	}
 24	function components(value: unknown, empty = false): value is string[] {
 25	  return Array.isArray(value) && value.length <= 32 && (empty || value.length > 0) &&
