 34	    case 'bind': return root(value.root)
 35	    case 'capabilities': case 'dispose': return true
 36	    case 'mkdir': return components(value.path)
 37	    case 'read': return components(value.path) && integer(value.offset, 0, MAX_FILE_BYTES) &&
