 39	    case 'list': return components(value.path, true) && integer(value.limit, 1, 128) &&
 40	      (value.cursor === null || token(value.cursor))
 41	    case 'write-open': return components(value.path) && integer(value.maxBytes, 0, MAX_FILE_BYTES)
 42	    case 'write-chunk': {
