 57	  }
 58	}
 59	function validCommand(item: Record<string, unknown>, session: FilesystemSession, nextId: number, bound: boolean, nowMs: number): item is Record<string, unknown> & FilesystemCommand {
 60	    if (typeof item.operation !== 'string' || !Object.hasOwn(operationKeys, item.operation)) return false
 61	    const keys = [...envelopeKeys, ...operationKeys[item.operation]]
 62	    if (item.operation === 'write-close' && Object.hasOwn(item, 'retainForPublication')) keys.push('retainForPublication')
