 72	export class FilesystemCommandGate {
 73	  private unusable = false
 74	  private bound = false
 75	  private nextId = 1
 76	  private pending: FilesystemCommand | null = null
 77	  private readonly session: FilesystemSession
 78	  constructor(session: FilesystemSession) {
 79	    if (!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(session.session) ||
 80	      !integer(session.generation, 1, Number.MAX_SAFE_INTEGER)) throw new TypeError('INVALID_FILESYSTEM_SESSION')
 81	    this.session = { ...session }
 82	  }
 83	  get closed(): boolean { return this.unusable }
 84	  private refuse(): null { this.unusable = true; this.pending = null; return null }
 85	  accept(frame: Uint8Array, nowMs: number): FilesystemCommand | null {
 86	    if (this.unusable || this.pending || !Number.isFinite(nowMs) || nowMs < 0 ||
 87	      frame.byteLength > MAX_FRAME_BYTES || frame.byteLength < 3) return this.refuse()
 88	    let text: string, value: unknown
 89	    try {
 90	      text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(frame)
 91	      if (!text.endsWith('\n') || text.slice(0, -1).includes('\n')) return this.refuse()
 92	      text = text.slice(0, -1)
 93	      value = JSON.parse(text)
 94	      // Dedicated host transport uses one compact canonical encoding. This also refuses duplicate keys.
 95	      if (JSON.stringify(value) !== text) return this.refuse()
 96	    } catch { return this.refuse() }
 97	    if (!value || typeof value !== 'object' || Array.isArray(value)) return this.refuse()
 98	    const item = value as Record<string, unknown>
 99	    if (!validCommand(item, this.session, this.nextId, this.bound, nowMs)) return this.refuse()
100	    this.pending = item
101	    return this.pending
102	  }
103	  complete(requestId: number, success: boolean): boolean {
104	    if (this.unusable || !this.pending || requestId !== this.pending.requestId || typeof success !== 'boolean') {
105	      this.refuse(); return false
106	    }
107	    const operation = this.pending.operation
108	    this.pending = null
109	    if (!success || operation === 'dispose' || this.nextId === Number.MAX_SAFE_INTEGER) this.unusable = true
110	    else { if (operation === 'bind') this.bound = true; this.nextId++ }
111	    return true
112	  }
113	}
