 49	  private readonly session = randomUUID()
 50	  private readonly gate: FilesystemCommandGate
 51	  private nextId = 1
 52	  private pending: Pending | null = null
 53	  private unusable = false
 54	  private bytes = Buffer.alloc(0)
 55	  private stderrBytes = 0
 56	  private helperClock = 0
 57	  private receivedAt = performance.now()
 58	  private constructor(executable: string, private readonly options: NativeTransportOptions) {
 59	    this.gate = new FilesystemCommandGate({ session: this.session, generation: options.generation })
 60	    this.child = spawn(executable, [], { windowsHide: true, stdio: 'pipe', shell: false })
 61	    this.exit = new Promise(resolve => this.child.once('close', code => {
 62	      if (this.pending) this.fail('FILESYSTEM_HELPER_CLOSED')
 63	      this.unusable = true; resolve(code)
 64	    }))
 65	    this.child.once('error', () => this.fail('FILESYSTEM_HELPER_UNAVAILABLE'))
 66	    this.child.stdout.on('data', (chunk: Buffer) => this.reply(chunk))
 67	    this.child.stderr.on('data', (chunk: Buffer) => { this.stderrBytes += chunk.length; if (this.stderrBytes > 4096) this.fail('FILESYSTEM_STDERR_LIMIT') })
