 70	  static async connect(options: NativeTransportOptions): Promise<WindowsFilesystemTransport> {
 71	    if (process.platform !== 'win32' || process.arch !== 'x64') throw new FilesystemTransportError('BACKEND_UNAVAILABLE', 'WINDOWS_BACKEND_UNAVAILABLE')
