134	    } catch { this.fail('INVALID_FILESYSTEM_REPLY') }
135	  }
136	  async dispose(): Promise<void> {
137	    if (!this.unusable && !this.pending) await this.request({ operation: 'dispose' })
138	    else this.fail('FILESYSTEM_SESSION_CLOSED')
139	    await this.exit
140	  }
141	}

